// Edit these values for each manual run.
const config = {
  source_url: 'https://www.youtube.com/watch?v=Sn3H5UzsDoY',
  pilot: true,
  force_reprocess: false,
  // Pilot only: if no clip reaches SCORING_V1, continue with the best non-HIGH clip as REVIEW.
  allow_below_threshold: true,
  max_candidates: 10,
};

// Webhook runs (scripts/run-pilot.sh) override the defaults above.
let body = {};
try { body = $('Webhook').first().json.body || {}; } catch { /* manual run */ }
if (body.source_url) config.source_url = String(body.source_url);
if (body.force_reprocess !== undefined) config.force_reprocess = body.force_reprocess === true || body.force_reprocess === 'true';
if (body.allow_below_threshold !== undefined) config.allow_below_threshold = body.allow_below_threshold === true || body.allow_below_threshold === 'true';

const m = config.source_url.match(/(?:v=|youtu\.be\/|shorts\/|live\/)([A-Za-z0-9_-]{11})/);
if (!m) throw new Error('CONFIG_INVALID: could not extract YouTube video id from source_url');

return [{ json: { ...config, source_video_id: m[1], started_at: new Date().toISOString() } }];

const res = $input.first().json;
if (!res?.job_id) throw new Error(`CLIPPER_SUBMIT_FAILED: ${JSON.stringify(res).slice(0, 300)}`);
return [{ json: { ...$('CONFIG').first().json, job_id: res.job_id } }];

// Polls a clipper job; loops back to WAIT PREPARE while queued/running.
const MAX_POLLS = 120;
const res = $input.first().json;
const ctx = $('WAIT PREPARE').first().json;
const poll = $runIndex + 1;

if (res?.status === 'queued' || res?.status === 'running') {
  if (poll >= MAX_POLLS) throw new Error(`CLIPPER_TIMEOUT: job ${ctx.job_id} still ${res.status} after ${poll} polls`);
  return [{ json: { ...ctx, job_status: res.status, polls: poll } }];
}
if (res?.status === 'done' && res.result) {
  return [{ json: { ...ctx, job_status: 'done', polls: poll, result: res.result } }];
}
throw new Error(`${res?.error_code ?? 'CLIPPER_FAILED'}: ${res?.error_message ?? JSON.stringify(res).slice(0, 300)}`);

// Asks the LLM to propose clip windows (full sentences) directly from the transcript.
const ctx = $input.first().json;
const prep = ctx.result;
const config = $('CONFIG').first().json;
if (!prep.sentences?.length) throw new Error('TRANSCRIPT_EMPTY: no sentences');

const mmss = (s) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;
const lines = prep.sentences.map((s) => `[${s.id}] (${mmss(s.start)} · ${(s.end - s.start).toFixed(1)}s) ${s.text}`).join('\n');

const SYSTEM = `Você é editor de um canal independente de YouTube Shorts com declarações públicas
de Lucas Pavanato. Você recebe a transcrição completa de um vídeo, dividida em FRASES numeradas.

TAREFA
Proponha até ${config.max_candidates} trechos candidatos a Shorts.

REGRAS DO TRECHO (resposta)
- Somente trechos em que LUCAS PAVANATO é quem fala (identifique pelo contexto: apresentação
  do entrevistador, perguntas dirigidas a ele, referências à própria trajetória). Se houver
  outros entrevistados, NÃO selecione falas deles como conteúdo principal.
- start_id/end_id = números das frases [n] (inclusive). Cada linha mostra a duração da frase
  (ex.: "4.2s"): SOME as durações e mantenha o total entre 20 e 60 segundos. Se a resposta
  inteira for mais longa, escolha o MELHOR sub-trecho autossuficiente dela.
- COMEÇO: na primeira frase da ideia, idealmente já no ponto mais forte. Evite começar com
  "então", "e aí", "como eu falei", ou com resposta que dependa de algo não incluído.
- FIM: a ideia precisa estar CONCLUÍDA. end_id deve ser a frase que fecha o raciocínio; nunca
  termine no meio de uma enumeração, argumento ou frase interrompida.
- Deve ser compreensível sozinho e NÃO pode alterar o sentido da fala.
- Prefira: resposta forte, contraste, conflito real, dado concreto, posição clara, tema atual.
- Não avalie se concorda politicamente. Não selecione com base em ideologia.
- Trechos não podem se sobrepor.
- A transcrição automática às vezes junta falas de pessoas diferentes numa mesma frase. Se a
  frase start_id começa com palavras de OUTRA pessoa (ex.: o mediador anunciando a réplica),
  copie essas palavras iniciais EXATAMENTE em start_trim_text; o corte começará depois delas.
  Idem para end_trim_text: palavras finais da frase end_id que são de outra pessoa ou que
  começam um raciocínio que não termina. Use "" quando não houver.

CONTEXTO (para o espectador saber o que ele está respondendo)
- Se a resposta é a uma PERGUNTA de um entrevistador (ou provocação de outro participante)
  que aparece logo antes e dura até ~15 segundos, informe question_start_id/question_end_id
  com as frases EXATAS da pergunta. Senão use -1 nos dois.
- context_text: SEMPRE preencha. Uma frase factual (máx. 90 caracteres) dizendo o que está
  sendo respondido/discutido, sem opinião, sem adjetivos, sem atribuir nada que não foi dito.
  Ex.: "Folha pergunta sobre críticas que ele já fez a Bolsonaro".

speaker_confidence: 0–100, certeza de que a RESPOSTA é de Lucas Pavanato.
score: 0–10, potencial de retenção.`;

const schema = {
  type: 'object', additionalProperties: false, required: ['candidates'],
  properties: {
    candidates: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false,
        required: ['start_id', 'end_id', 'start_trim_text', 'end_trim_text', 'question_start_id', 'question_end_id', 'context_text',
          'speaker_confidence', 'score', 'title_hint', 'why'],
        properties: {
          start_id: { type: 'integer' }, end_id: { type: 'integer' },
          start_trim_text: { type: 'string' }, end_trim_text: { type: 'string' },
          question_start_id: { type: 'integer' }, question_end_id: { type: 'integer' },
          context_text: { type: 'string' },
          speaker_confidence: { type: 'integer', minimum: 0, maximum: 100 },
          score: { type: 'number', minimum: 0, maximum: 10 },
          title_hint: { type: 'string' }, why: { type: 'string' },
        },
      },
    },
  },
};

return [{ json: { ...ctx, request: { provider: 'auto', system: SYSTEM, schema,
  prompt: `VÍDEO: "${prep.title}" — canal ${prep.channel} (publicado ${prep.upload_date})\n\nTRANSCRIÇÃO (frases):\n${lines}` } } }];

// Validates finder output and maps sentence ids to the clip schema used by the judge.
const res = $input.first().json;
const ctx = $('BUILD FINDER REQUEST').first().json;
const prep = ctx.result;
if (!res?.ok || !Array.isArray(res.json?.candidates)) {
  throw new Error(`${res?.error_code ?? 'LLM_INVALID_JSON'}: clip finder ${res?.error_message ?? 'returned no candidates'}`);
}
const byId = new Map(prep.sentences.map((s) => [s.id, s]));
const norm = (t) => t.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9 ]/g, '').split(/\s+/).filter(Boolean);
const textOf = (a, b) => prep.sentences.filter((s) => s.id >= a && s.id <= b).map((s) => s.text).join(' ');
// Number of words to skip at the start/end of a sentence when trim text matches it exactly.
const skipCount = (sentence, trim, atEnd) => {
  const t = norm(trim || '');
  if (!t.length) return 0;
  const words = sentence.text.split(/\s+/).filter(Boolean);
  const ws = norm(sentence.text);
  const slice = atEnd ? ws.slice(ws.length - t.length) : ws.slice(0, t.length);
  if (t.length >= ws.length || slice.join(' ') !== t.join(' ')) return 0;
  // norm() can merge/drop tokens; fall back to raw word count of the matched prefix/suffix
  return Math.min(t.length, words.length - 1);
};
const used = [];
const clips = [];
const rejected = [];
for (const c of res.json.candidates) {
  const why = (r) => rejected.push({ start_id: c.start_id, end_id: c.end_id, reject: r });
  const a = byId.get(c.start_id);
  const b = byId.get(c.end_id);
  if (!a || !b || c.end_id < c.start_id) { why('invalid ids'); continue; }
  const answerDur = b.end - a.start;
  if (answerDur < 15 || answerDur > 75) { why(`answer ${answerDur.toFixed(1)}s`); continue; }
  if (c.speaker_confidence < 60) { why(`speaker_confidence ${c.speaker_confidence}`); continue; }

  const parts = [];
  let question = null;
  const qa = byId.get(c.question_start_id);
  const qb = byId.get(c.question_end_id);
  if (qa && qb && c.question_end_id >= c.question_start_id && c.question_end_id < c.start_id) {
    const qDur = qb.end - qa.start;
    if (qDur <= 18 && a.start - qb.end <= 30) {
      parts.push({ start_id: c.question_start_id, end_id: c.question_end_id, role: 'question' });
      question = textOf(c.question_start_id, c.question_end_id);
    }
  }
  const skipStart = skipCount(a, c.start_trim_text, false);
  const skipEnd = c.end_id === c.start_id && skipStart ? 0 : skipCount(b, c.end_trim_text, true);
  parts.push({ start_id: c.start_id, end_id: c.end_id, role: 'answer', skip_words_start: skipStart, skip_words_end: skipEnd });
  let answerText = textOf(c.start_id, c.end_id).split(/\s+/);
  answerText = answerText.slice(skipStart, answerText.length - skipEnd).join(' ');
  const span = [parts[0].start_id, c.end_id].map((id) => byId.get(id));
  const start = span[0].start;
  const end = span[1].end;
  if (used.some(([s, e]) => start < e && end > s)) { why('overlap'); continue; }
  used.push([start, end]);

  const duration = parts.reduce((t, p) => t + byId.get(p.end_id).end - byId.get(p.start_id).start, 0);
  clips.push({
    clip_id: `${prep.video_id}_${parts[0].start_id}-${c.end_id}`,
    parts, duration: Math.round(duration),
    question, context_text: (c.context_text || '').slice(0, 120),
    title: c.title_hint, transcript: answerText, trims: { start: c.start_trim_text, end: c.end_trim_text, skipStart, skipEnd },
    viral_score: c.score, viral_reason: c.why, speaker_confidence: c.speaker_confidence,
    related_topic: '',
    source_url: prep.source_url, source_video_id: prep.video_id,
    source_title: prep.title, source_channel: prep.channel,
  });
}
console.log(JSON.stringify({ proposed: res.json.candidates.length, accepted: clips.length, rejected }));
if (clips.length === 0) throw new Error(`NO_CLIPS_RETURNED: finder proposed ${res.json.candidates.length}, none valid`);
return clips.map((c) => ({ json: c }));

// Validates each judge response and computes the final score deterministically.
const MAX = { hook_score: 25, context_score: 20, conflict_score: 15, current_score: 15, clarity_score: 10, retention_score: 15 };
const PENALTIES = {
  penalty_meaning_change: 20, penalty_missing_context: 20, penalty_slow_start: 15,
  penalty_repetitive: 10, penalty_title_needs_exaggeration: 20,
  penalty_abrupt_end: 15, penalty_unfaithful_context: 20,
};
const clips = $('BUILD JUDGE REQUEST').all();

return $input.all().map((item, i) => {
  const { request, ...clip } = clips[i].json;
  const res = item.json;
  const j = res?.json;

  const problems = [];
  if (!res?.ok) problems.push(`${res?.error_code ?? 'LLM_FAILED'}: ${res?.error_message ?? 'no response'}`);
  else if (!j || typeof j !== 'object') problems.push('LLM_INVALID_JSON: missing json');
  else {
    for (const [k, max] of Object.entries(MAX)) {
      if (!Number.isInteger(j[k]) || j[k] < 0 || j[k] > max) problems.push(`LLM_INVALID_JSON: ${k}=${j[k]}`);
    }
    for (const k of Object.keys(PENALTIES)) if (typeof j[k] !== 'boolean') problems.push(`LLM_INVALID_JSON: ${k}`);
    if (!['LOW', 'MEDIUM', 'HIGH'].includes(j.risk)) problems.push(`LLM_INVALID_JSON: risk=${j.risk}`);
  }

  if (problems.length) {
    return { json: { ...clip, judge_ok: false, judge_error: problems.join('; '), score: null, risk: null } };
  }

  const base = Object.keys(MAX).reduce((s, k) => s + j[k], 0);
  const penalty = Object.entries(PENALTIES).reduce((s, [k, v]) => s + (j[k] ? v : 0), 0);
  return {
    json: {
      ...clip,
      judge_ok: true,
      judge_provider: res.provider,
      judge_model: res.model,
      score_base: base,
      score_penalty: penalty,
      score: Math.max(0, base - penalty),
      ...j,
    },
  };
});

// SCORING_V1 (docs/plan.md §23): score >= 75 AND risk != HIGH, score DESC, LIMIT 1.
const MIN_SCORE = 75;
const all = $input.all().map((i) => i.json);
const judged = all.filter((c) => c.judge_ok);

if (judged.length === 0) {
  throw new Error(`LLM_INVALID_JSON: no clip could be judged (${all.map((c) => c.judge_error).join(' | ')})`);
}

const ranked = [...judged].sort((a, b) => b.score - a.score || b.viral_score - a.viral_score);
const eligible = ranked.filter((c) => c.score >= MIN_SCORE && c.risk !== 'HIGH');

const summary = ranked.map((c) => ({
  clip_id: c.clip_id, score: c.score, risk: c.risk, eligible: eligible.includes(c), title: c.title,
}));
console.log(JSON.stringify({ judged: judged.length, failed: all.length - judged.length, ranking: summary }));

if (eligible.length === 0) {
  const config = $('CONFIG').first().json;
  const fallback = ranked.find((c) => c.risk !== 'HIGH');
  if (config.pilot && config.allow_below_threshold && fallback) {
    return [{ json: { ...fallback, status: 'REVIEW', below_threshold: true, scoring_version: 'SCORING_V1', ranking: summary } }];
  }
  throw new Error(`ALL_CLIPS_REJECTED: best score ${ranked[0].score} (${ranked[0].risk}), threshold ${MIN_SCORE}`);
}

return [{ json: { ...eligible[0], status: 'SELECTED', below_threshold: false, scoring_version: 'SCORING_V1', ranking: summary } }];

const res = $input.first().json;
if (!res?.job_id) throw new Error(`RENDER_SUBMIT_FAILED: ${JSON.stringify(res).slice(0, 300)}`);
return [{ json: { ...$('APPLY PROOFREAD').first().json, job_id: res.job_id } }];

// Polls a clipper job; loops back to WAIT RENDER while queued/running.
const MAX_POLLS = 60;
const res = $input.first().json;
const ctx = $('WAIT RENDER').first().json;
const poll = $runIndex + 1;

if (res?.status === 'queued' || res?.status === 'running') {
  if (poll >= MAX_POLLS) throw new Error(`RENDER_TIMEOUT: job ${ctx.job_id} still ${res.status} after ${poll} polls`);
  return [{ json: { ...ctx, job_status: res.status, polls: poll } }];
}
if (res?.status === 'done' && res.result) {
  return [{ json: { ...ctx, job_status: 'done', polls: poll, result: res.result } }];
}
throw new Error(`${res?.error_code ?? 'RENDER_FAILED'}: ${res?.error_message ?? JSON.stringify(res).slice(0, 300)}`);

const ctx = $input.first().json;
const { result, job_id, job_status, polls, ...clip } = ctx;
if (result.width !== 1080 || result.height !== 1920) throw new Error(`RENDER_FAILED: unexpected size ${result.width}x${result.height}`);
return [{ json: { ...clip, status: clip.status, video_file: result.container_path, video_file_name: result.file_name,
  render: { width: result.width, height: result.height, duration: result.duration, shots: result.shots, fit_ratio: result.fit_ratio } } }];

// Proofreads the captions of the selected clip: only evident ASR errors, never style or meaning.
const clip = $input.first().json;
const prep = $('BUILD FINDER REQUEST').first().json.result;
const ids = new Set();
for (const p of clip.parts) for (let i = p.start_id; i <= p.end_id; i++) ids.add(i);
const sentences = prep.sentences.filter((s) => ids.has(s.id));
const around = prep.sentences.filter((s) => s.id >= Math.min(...ids) - 4 && s.id <= Math.max(...ids) + 2);

const SYSTEM = `Você revisa legendas geradas por transcrição automática (Whisper) de um vídeo em português.

Corrija SOMENTE erros evidentes de transcrição: nomes próprios, números, datas, siglas,
instituições, e palavras trocadas por outras de som parecido que o CONTEXTO deixa claro
(ex.: "presos do Rio de Janeiro" quando o assunto são os presos do 8 de janeiro).

NÃO reescreva o estilo, NÃO corrija a gramática da fala, NÃO remova hesitações ou repetições,
NÃO resuma, NÃO mude o sentido. Na dúvida, não corrija.

Retorne apenas as frases que precisam de correção, com o texto COMPLETO corrigido da frase,
e em "changes" descreva cada troca no formato "antes → depois".`;

const schema = {
  type: 'object', additionalProperties: false, required: ['fixes'],
  properties: { fixes: { type: 'array', items: {
    type: 'object', additionalProperties: false, required: ['id', 'text', 'changes'],
    properties: { id: { type: 'integer' }, text: { type: 'string' }, changes: { type: 'array', items: { type: 'string' } } },
  } } },
};

return [{ json: { ...clip, request: { provider: 'auto', system: SYSTEM, schema, prompt:
`VÍDEO: "${prep.title}" — ${prep.channel}

CONTEXTO (frases ao redor, não corrigir):
${around.map((s) => `[${s.id}] ${s.text}`).join('\n')}

FRASES A REVISAR:
${sentences.map((s) => `[${s.id}] ${s.text}`).join('\n')}` } } }];

// Applies proofreading fixes (only to sentences of this clip). Failures are logged, not fatal.
const res = $input.first().json;
const { request, ...clip } = $('BUILD PROOFREAD REQUEST').first().json;
const ids = new Set();
for (const p of clip.parts) for (let i = p.start_id; i <= p.end_id; i++) ids.add(i);
const fixes = {};
const changes = [];
if (res?.ok && Array.isArray(res.json?.fixes)) {
  for (const f of res.json.fixes) {
    if (!ids.has(f.id) || !f.text?.trim()) continue;
    fixes[String(f.id)] = f.text.trim();
    changes.push(...(f.changes || []).map((c) => `[${f.id}] ${c}`));
  }
} else {
  console.log(`PROOFREAD_SKIPPED: ${res?.error_code ?? 'no response'} ${res?.error_message ?? ''}`);
}
console.log(JSON.stringify({ proofread_changes: changes }));
return [{ json: { ...clip, sentence_fixes: fixes, proofread_changes: changes } }];

// Idempotency (docs/plan.md §31): skip videos already in flight or published, unless forced.
const config = $('CONFIG').first().json;
const row = $input.all().map((i) => i.json).find((r) => r.youtube_id === config.source_video_id);
const STALE_MS = 2 * 60 * 60 * 1000; // a PROCESSING row older than this is a crashed run
const now = new Date();
if (row && !config.force_reprocess) {
  const active = ['PROCESSING', 'CLIPPED', 'SELECTED'].includes(row.status);
  const stale = active && now - new Date(row.updated_at) > STALE_MS;
  if (row.status === 'UPLOADED' || (active && !stale)) {
    console.log(`SKIPPED_DUPLICATE: ${config.source_video_id} is ${row.status} (youtube_output_id=${row.youtube_output_id || '-'})`);
    return [];
  }
}
return [{ json: {
  youtube_id: config.source_video_id,
  source_url: config.source_url,
  execution_id: String($execution.id),
  status: 'PROCESSING',
  error_reason: '',
  discovered_at: row?.discovered_at ?? now.toISOString(),
  created_at: row?.created_at ?? now.toISOString(),
  updated_at: now.toISOString(),
} }];

// Title + description (docs/plan.md §24-25) in a single call.
const clip = $input.first().json;
const SYSTEM = `Você é editor de YouTube Shorts de um canal independente (canal de fã, não oficial)
com declarações públicas de Lucas Pavanato. Grafia correta do nome: Pavanato (um T).

TÍTULO
- Alta retenção, despertando curiosidade SEM inventar fatos e sem alterar o significado da fala.
- Prefira: curiosidade, contraste, resposta, surpresa, conflito real, assunto atual, afirmação
  forte realmente existente no vídeo.
- Evite: clickbait falso, caixa alta excessiva, afirmações não presentes, insultos, inferências
  sobre intenção, propaganda política personalizada.
- Máximo 70 caracteres. Sem hashtags no título. Crie 5 opções e escolha a melhor.

DESCRIÇÃO
- Máximo 350 caracteres. NÃO inclua URL, linha de fonte, aviso de canal de fã nem hashtags:
  isso é adicionado automaticamente depois.
- Explique brevemente o contexto, deixe claro que é um trecho, identifique a fonte original,
  não atribua nada que não tenha sido dito, tom editorial.

TAGS: 5 a 8 tags curtas em português (sem #).
HASHTAGS: 3 a 5, sem espaços, começando com #; não inclua #LucasPavanato nem #Shorts (já entram).`;

const schema = {
  type: 'object', additionalProperties: false,
  required: ['title', 'alternatives', 'hook', 'description', 'tags', 'hashtags'],
  properties: {
    title: { type: 'string' }, alternatives: { type: 'array', items: { type: 'string' } },
    hook: { type: 'string' }, description: { type: 'string' },
    tags: { type: 'array', items: { type: 'string' } }, hashtags: { type: 'array', items: { type: 'string' } },
  },
};
return [{ json: { ...clip, request: { provider: 'auto', system: SYSTEM, schema, prompt:
`FONTE: ${clip.source_channel} — "${clip.source_title}"
URL: ${clip.source_url}

CONTEXTO: ${clip.context_text || '-'}
PERGUNTA INCLUÍDA: ${clip.question || '-'}
ASSUNTO: ${clip.main_topic}

TRANSCRIÇÃO DA RESPOSTA:
${clip.transcript}` } } }];

// Validates metadata and appends the mandatory source/notice lines (never left to the LLM).
const res = $input.first().json;
const { request, ...clip } = $('BUILD METADATA REQUEST').first().json;
if (!res?.ok || !res.json?.title) throw new Error(`${res?.error_code ?? 'LLM_INVALID_JSON'}: metadata ${res?.error_message ?? 'missing title'}`);
const m = res.json;

const clean = (s) => String(s || '').replace(/[<>]/g, '').replace(/\s+/g, ' ').trim();
let title = clean(m.title).replace(/#\S+/g, '').trim();
if (!title) throw new Error('LLM_INVALID_JSON: empty title');
if (title.length > 100) title = title.slice(0, 97).replace(/\s+\S*$/, '') + '...';
if (/pavanatto/i.test(title + m.description)) throw new Error('METADATA_INVALID: misspelled name (Pavanatto)');

const tag = (h) => '#' + String(h).replace(/^#/, '').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Za-z0-9_]/g, '');
const hashtags = [...new Set(['#LucasPavanato', ...(m.hashtags || []).map(tag), '#Shorts'])].filter((h) => h.length > 2).slice(0, 6);
let body = clean(m.description);
if (body.length > 400) body = body.slice(0, 397).replace(/\s+\S*$/, '') + '...';
const description = [
  body,
  '',
  `Fonte: ${clip.source_channel} — ${clip.source_url}`,
  'Trecho editado. Canal de fã, independente e não oficial; não representa Lucas Pavanato nem sua equipe.',
  '',
  hashtags.join(' '),
].join('\n');
const tags = [...new Set(['Lucas Pavanato', 'Pavanato', ...(m.tags || []).map(clean)])].filter(Boolean).slice(0, 12);

return [{ json: { ...clip, title, title_alternatives: m.alternatives, hook: m.hook, description, tags } }];

const c = $input.first().json;
